// GLSL Simplex Noise Function
vec3 mod289(vec3 x) {
  return x - floor(x * (1.0 / 289.0)) * 289.0;
}

vec2 mod289(vec2 x) {
  return x - floor(x * (1.0 / 289.0)) * 289.0;
}

vec3 permute(vec3 x) {
  return mod289(((x * 34.0) + 1.0) * x);
}

float snoise(vec2 v) {
  const vec4 C = vec4(0.211324865405187,  // (3.0 - sqrt(3.0)) / 6.0
                      0.366025403784439,  // 0.5 * (sqrt(3.0) - 1.0)
                     -0.577350269189626,  // -1.0 + 2.0 * C.x
                      0.024390243902439); // 1.0 / 41.0
  vec2 i = floor(v + dot(v, C.yy));
  vec2 x0 = v - i + dot(i, C.xx);

  vec2 i1;
  i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);

  vec4 x12 = x0.xyxy + C.xxzz;
  x12.xy -= i1;

  i = mod289(i);
  vec3 p = permute(permute(i.y + vec3(0.0, i1.y, 1.0))
                         + i.x + vec3(0.0, i1.x, 1.0));

  vec3 m = max(0.5 - vec3(dot(x0, x0), dot(x12.xy, x12.xy), dot(x12.zw, x12.zw)), 0.0);
  m = m * m;
  m = m * m;

  vec3 x = 2.0 * fract(p * C.www) - 1.0;
  vec3 h = abs(x) - 0.5;
  vec3 ox = floor(x + 0.5);
  vec3 a0 = x - ox;

  m *= 1.79284291400159 - 0.85373472095314 * (a0 * a0 + h * h);

  vec3 g;
  g.x = a0.x * x0.x + h.x * x0.y;
  g.yz = a0.yz * x12.xz + h.yz * x12.yw;

  return 130.0 * dot(m, g);
}

float sdOrientedBox( in vec2 p, in vec2 a, in vec2 b, float th )
{
    float l = length(b-a);
    vec2  d = (b-a)/l;
    vec2  q = p-(a+b)*0.5;
          q = mat2(d.x,-d.y,d.y,d.x)*q;
          q = abs(q)-vec2(l*0.5,th);
    return length(max(q,0.0)) + min(max(q.x,q.y),0.0);    
}

float sdSegment( in vec2 p, in vec2 a, in vec2 b )
{
    vec2 pa = p-a, ba = b-a;
    float h = clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 );
    return length( pa - ba*h );
}


float roadY(float x) {
    float frequency = 0.02; // Adjust for desired curviness
    float amplitude = 15.0; // Adjust for desired vertical range
    float baseOffset = 0.0; // Base height offset
    return amplitude * snoise(vec2(x * frequency, 0.0)) + baseOffset;// + 0.05 * sin(x * 4.0);
}


float pathAt(in float x) {
    //return sin(x / 2.0) + sin(x / 3.0);
    return roadY(x);
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float aspectRatio = iResolution.x / iResolution.y;
    vec2 uv = fragCoord/iResolution.xy * 2.0 - 1.0;
    uv.x = uv.x * aspectRatio;

    vec2 cameraPos = vec2(iTime, pathAt(iTime));
    uv += cameraPos;

    vec2 tile = floor(uv / 0.4);

    float pathY = pathAt(uv.x);

    vec3 terrainColor = mix(vec3(0.0, 0.4, 0.0), vec3(0.0, 0.45, 0.0), step(0.2, snoise(uv / 2.0)));
    //float brightness = float(int(mod(tile.x + tile.y, 2.0))) * 0.02;
    //vec3 terrainColor = vec3(0.0, brightness + 0.4, 0.0);

    float onPath = 1.0 - step(0.10, abs(uv.y - pathY));
    vec3 roadColor = vec3(0.3, 0.3, 0.3);

    //vec2 center = vec2(0.5 + )
    float lookAheadTime = 0.2;
    vec2 futureCameraPos = vec2(iTime + lookAheadTime, pathAt(iTime + lookAheadTime));
    vec2 steerDirection = (futureCameraPos - cameraPos) / distance(cameraPos, futureCameraPos);
    vec2 carFront = cameraPos + steerDirection * 0.11;
    float isCarPixel = 1.0 - step(0.04, sdOrientedBox(uv, cameraPos, carFront, 0.01));
    vec3 carColor = vec3(0.6, 0.0, 0.0);

    vec3 baseColor = isCarPixel * carColor + ((1.0 - isCarPixel) * roadColor * onPath + terrainColor * (1.0 - onPath));
    float dayTime = abs(sin(iTime / 25.0));
    vec3 ambientLight = mix(vec3(0.3, 0.05, 0.05), vec3(1.0, 1.0, 1.0), dayTime);

    float angle = acos(clamp(dot(steerDirection, normalize(uv - carFront)), -1.0, 1.0));
    float distanceToCarFront = distance(cameraPos, uv);
    float isInLightCone = (1.0 - step(0.6, dayTime)) * (1.0 - smoothstep(0.3, 0.4, abs(angle))) * (step(0.15, distanceToCarFront));
    float extraLightIntensity = isInLightCone * 3.0 * (1.0 - sqrt(distanceToCarFront / 2.0));
    vec3 extraLightColor = vec3(0.7, 0.7, 1.0);

    fragColor = vec4(baseColor * (ambientLight + extraLightIntensity * extraLightColor), 1.0);
}
